    const records = fs.existsSync(turn.eventsFile) ? fs.readFileSync(turn.eventsFile, "utf8").split(/\r?\n/).filter(Boolean).flatMap(line => { try { return [JSON.parse(line)]; } catch { return []; } }) : [];
